checks=[]
for loc,articles in out.items():
 existing=(p.parents[2]/'src/app/content'/loc/'articles.ts').read_text()
 for slug,a in articles.items():
  orig=source[slug]
  assert set(a)==set(orig),(loc,slug,'keys')
  assert len(a['sections'])==len(orig['sections'])
  assert [len(x['body']) for x in a['sections']]==[len(x['body']) for x in orig['sections']]
  assert len(a['faq'])==3 and len(a['practical'])==len(orig['practical'])
  assert a['updated']=='2026-10-21' and a['claims']==orig['claims']
  assert [s['url'] for s in a['sources']]==[s['url'] for s in orig['sources']]
  assert a['seeAlso']==orig['seeAlso']
  for related in a['seeAlso']:assert re.search(r"['\"]"+re.escape(related)+r"['\"]\s*:",existing),(loc,related)
  assert len(a['description'])<160,(loc,slug,len(a['description']))
  assert 'Arte Soft' in a['lede'] and 'Cloud Calendars' in a['lede']
  checks.append({'locale':loc,'slug':slug,'sections':len(a['sections']),'paragraphs':[len(x['body']) for x in a['sections']],'faq':3,'steps':len(a['practical']),'sources':len(a['sources']),'seeAlso':a['seeAlso'],'metaCharacters':len(a['description'])})
 (p/(loc+'.json')).write_text(json.dumps(articles,ensure_ascii=False,indent=2)+'\n')
(p/'audit.json').write_text(json.dumps({'status':'8 translated objects; proposals only','source':str(src),'sourceSha256':hashlib.sha256(src.read_bytes()).hexdigest(),'scope':'Only forecast-beside-every-event and planning-outdoors-without-being-rained-on in de-DE/es-ES/fr-FR/it. No source integration, native changes, ASC mutation or deployment.','preserved':'Canonical slugs, key shape, publication/update date 2026-10-21, all paragraphs, 3 FAQ per article, practical steps, empty claims, primary source URLs, developer disclosure and existing available related links.','qualification':'No promise of complete hourly coverage, event-address-controlled weather, automatically saved events, guaranteed dry periods or universal precipitation threshold. Editing permissions remain separate from weather.','translationConfidence':'medium-high, model-authored; no independent native review','style':'Natural prose with every substantive point retained. Outdoor lede renders replacing guessing as deliberate comparison without implying weather certainty.','validation':checks},ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'objects':len(checks),'metaLengths':[x['metaCharacters'] for x in checks],'validation':'pass'}))
